#!/usr/bin/env bun
/**
 * Writes the token layer from `helix/styles/src/tokens.ts`.
 *
 * Two outputs from one source: the semantic block inside `tokens.css`, and
 * `tokens.json` for everything that needs to know a token's name without
 * parsing a stylesheet to find out.
 *
 * **The stylesheet was the source and had no reader that could be checked.**
 * `docs/16-token-reference.md` was generated by parsing it, and the ten
 * Foundations pages were written by a person reading it: two token names in
 * those pages did not exist, and a one-line diff found them hours after they
 * shipped. A JSON map is the reader those pages should have had.
 *
 * **Only the semantic block is generated.** The mode declarations around it,
 * `[data-color-mode]` and the `prefers-color-scheme` fallback, are structure
 * rather than tokens: they say which half of a `light-dark()` resolves, which
 * is one decision expressed four times and not a list of anything. They stay
 * hand-written in the file, above and below the generated region, and this
 * replaces what sits between the markers.
 *
 * The prose between tokens comes across as comments in the order it was
 * written, so the generated stylesheet reads the way the hand-written one did.
 * That is not decoration: most of the reasoning in this design system's colour
 * work is in those paragraphs.
 *
 * `bun run tokens:build` writes, `bun run check:tokens-layer` fails when the
 * outputs and the source disagree.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { formatted } from './lib/formatted.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const CSS = join(ROOT, 'helix/styles/src/tokens.css')
const JSON_OUT = join(ROOT, 'helix/styles/tokens.json')

/* The generated region, named in the file so a reader editing the stylesheet
   can see where their edit will be overwritten. */
const OPEN = '/* GENERATED from src/tokens.ts by `bun run tokens:build`. Do not edit below. */'
const CLOSE = '/* GENERATED end. */'

const { TOKENS } = await import('../../helix/styles/src/tokens.ts')

/* Read back out of the module's own source, because a comment is not a value
   and TypeScript does not hand one to a caller. The file is the source of both
   halves and this is the half the language throws away. */
const source = readFileSync(join(ROOT, 'helix/styles/src/tokens.ts'), 'utf8')
const body = source.slice(source.indexOf('export const TOKENS: Token[] = ['))

const declarations = []
/* The trailing comma is not optional to allow for: the formatter writes one
   whenever a pair does not fit on a line, which 37 of these do not, and a
   pattern without it silently read 140 of 177 tokens. Caught by diffing the
   output against the stylesheet it replaces. */
const pattern = /\/\*([\s\S]*?)\*\/|\[\s*'((?:[^'\\]|\\.)*)',\s*'((?:[^'\\]|\\.)*)'\s*,?\s*\]/g
for (const match of body.matchAll(pattern)) {
  if (match[1] !== undefined) {
    const lines = match[1]
      .trim()
      .split('\n')
      .map((line) => line.trim())
    declarations.push(
      lines.length === 1
        ? `  /* ${lines[0]} */`
        : `  /* ${lines[0]}\n${lines
            .slice(1)
            .map((line) => (line ? `     ${line}` : ''))
            .join('\n')} */`,
    )
    continue
  }
  const name = match[2].replace(/\\'/g, "'")
  const value = match[3].replace(/\\'/g, "'").replace(/\\\\/g, '\\')
  declarations.push(`  --helix-${name}: ${value};`)
}

const block = `${OPEN}\n:root,\n[data-helix-theme] {\n${declarations.join('\n')}\n}\n${CLOSE}`

const existing = readFileSync(CSS, 'utf8')
const before = existing.slice(0, existing.indexOf(OPEN))
const after = existing.slice(existing.indexOf(CLOSE) + CLOSE.length)
const css = formatted(`${before}${block}${after}`, 'tokens.css')

/* The JSON, which is what a document renders from and what an agent reads.
   
   **An array, not an object keyed by name.** Declaration order is content here:
   the surfaces read as a ladder and the sizes read as a scale, and both become
   a list the moment they are alphabetised. `useSortedKeys` would have done
   exactly that to an object and been right to, since nothing about an object
   promises an order. An array promises one. */
const entries = TOKENS.map(([name, value]) => ({
  category: name.split('-')[0],
  name: `--helix-${name}`,
  value,
}))
const categories = [...new Set(entries.map((entry) => entry.category))]
const json = `${JSON.stringify({ categories, count: entries.length, tokens: entries }, undefined, 2)}\n`

if (process.argv.includes('--check')) {
  const stale = [
    existing !== css ? 'tokens.css' : undefined,
    readFileSync(JSON_OUT, 'utf8') !== json ? 'tokens.json' : undefined,
  ].filter(Boolean)
  if (stale.length > 0) {
    console.error(`token layer: ${stale.join(' and ')} stale. Run \`bun run tokens:build\``)
    process.exit(1)
  }
  console.log(`token layer: ${TOKENS.length} tokens in ${categories.length} categories, current`)
} else {
  writeFileSync(CSS, css)
  writeFileSync(JSON_OUT, json)
  console.log(`token layer: ${TOKENS.length} tokens in ${categories.length} categories written`)
}
